import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["SH"]
vws = vals["SH"]

max_row = 14
max_col = 12  # A:L

def is_blank_row(r):
    for c in range(1, max_col + 1):
        v = vws.cell(row=r, column=c).value
        if v is None:
            continue
        if isinstance(v, str) and v.strip() == "":
            continue
        return False
    return True

kept_rows = [r for r in range(1, max_row + 1) if not is_blank_row(r)]

def clean_value(v):
    if v is None:
        return None
    if isinstance(v, str):
        v = v.strip()
        if v == "":
            return None
    return v

# Answer region: SH!A6:L11
for new_r in range(6, 12):
    for c in range(1, max_col + 1):
        if new_r <= len(kept_rows):
            old_r = kept_rows[new_r - 1]
            ws.cell(row=new_r, column=c).value = clean_value(vws.cell(row=old_r, column=c).value)
        else:
            ws.cell(row=new_r, column=c).value = None

print("kept_rows:", kept_rows)
print("A6:", ws["A6"].value, "G6:", ws["G6"].value, "L6:", ws["L6"].value)
print("A9:", ws["A9"].value, "L11:", ws["L11"].value)

wb.save(OUT)
